async (page) => {
  const results=[];
  const open=async(name)=>page.getByRole('button',{name,exact:true}).click();
  const role=async(name)=>page.locator(`[data-role=${name}]`).first().click();
  const fill=async(values)=>{for(const [k,v] of Object.entries(values))await page.locator(`#action-form [name=${k}]`).fill(String(v));};
  const submit=async()=>{await page.locator('#action-form button[type=submit]').click();await page.locator('#dialog').waitFor({state:'hidden'});};
  const action=async(name,values)=>{await open(name);if(values)await fill(values);await submit();};
  const check=async(names)=>{for(const n of names)await page.locator(`[name=${n}]`).check();};
  const assert=(ok,msg)=>{if(!ok)throw new Error(msg);};
  const text=()=>page.locator('main').innerText();
  const reset=async()=>{await role('dispatch');await page.locator('[data-action=qa]').first().click();await action('重置全部演示数据');await role('dispatch');};
  const select=async(id)=>page.locator(`button.order-link[data-order="${id}"]`).click();
  const promise=async()=>{await open('确认报价与承诺');await fill({basis:'DEMO 人工核验班次、容量与窗口'});await check(['address','measured','confirmed']);await submit();};
  const offer=async()=>{await open('选择车辆并派单');await page.locator('[name=vehicle][value=V01]').check();await submit();};
  const ready=async()=>{await role('driver');await action('接受配送任务');await role('warehouse');await open('复核装载并准备交接');await check(['dimension','pattern','packaging']);await fill({evidence:'DEMO-LOAD'});await submit();await role('driver');await action('点收货物并取货',{evidence:'DEMO-HANDOVER'});await action('确认出发');};
  await page.goto('http://127.0.0.1:4173/prototype/');await page.reload();await page.setViewportSize({width:1440,height:1100});await reset();
  await open('新建订单');await page.locator('#action-form button[type=submit]').click();assert((await page.locator('#form-error').innerText()).includes('必填'),'Missing validation');
  await fill({customer:'金边设计工作室 · 演示',destination:'金边演示收货点 D',cargo:'包装办公椅',qty:2,weight:15,length:60,width:50,height:80,amount:28});await submit();
  await action('编辑草稿',{cargo:'包装办公椅（已核实）'});assert((await text()).includes('已核实'),'Edit not persisted');await promise();await offer();await ready();
  await action('登记收款',{proof:'DEMO-CASH-004'});await action('记录签收',{receiver:'演示收货人',evidence:'DEMO-POD-004'});assert((await text()).includes('已申报 · 待核验'),'Delivery incorrectly settled finance');
  await role('finance');await action('核验收款',{evidence:'DEMO-COUNT-004'});await role('driver');await action('提交现金交款',{evidence:'DEMO-REMIT-004'});await role('finance');await action('核对司机交款',{evidence:'DEMO-CHECK-004'});await page.locator('[data-tab=finance]').click();assert((await page.locator('.detail-body').innerText()).includes('已结清'),'Cash reconciliation failed');results.push('新建、编辑、承诺、派单、接受、交接、签收、核验与交款 PASS');
  await page.screenshot({path:'E:/Dr.RouteFit/prototype/screenshots/finance-complete.png',fullPage:true});
  await role('dispatch');await page.locator('#search').fill('不存在的演示客户');assert((await text()).includes('没有匹配'),'Search no-results failed');await open('清除筛选');await page.locator('[data-filter=delivered]').click();assert((await page.locator('tbody').innerText()).includes('RF-1024-004'),'Status filter failed');await page.locator('[data-filter=all]').click();results.push('搜索、清空、状态筛选 PASS');
  await reset();await offer();await role('driver');await action('拒绝任务',{reason:'演示班次冲突'});await role('dispatch');assert((await text()).includes('待派单'),'Reject did not restore queue');await offer();await action('撤回提案');await offer();await page.locator('[data-action=qa]').first().click();await action('使当前提案过期');await role('dispatch');assert((await text()).includes('提案过期'),'Expiry missing');results.push('拒单、撤回、过期恢复 PASS');
  await select('RF-1024-002');await action('编辑草稿',{weight:2000});await promise();await open('选择车辆并派单');assert(await page.locator('[name=vehicle]:disabled').count()===2,'Overload not blocked');await page.getByRole('button',{name:'关闭对话框'}).click();await action('取消订单',{reason:'超载演示任务取消'});assert((await text()).includes('已取消'),'Cancel failed');results.push('超载候选阻断、取消保留历史 PASS');
  await reset();await offer();await ready();await page.locator('[data-action=qa]').first().click();await page.locator('[data-mode=offline]').click();await action('登记收款',{proof:'DEMO-OFFLINE-CASH'});await action('记录签收',{count:2,receiver:'演示部分收货人',evidence:'DEMO-OFFLINE-POD'});assert((await text()).includes('2 项待同步'),'Offline queue missing');await open('恢复正常');await page.locator('[data-driver-tab=sync]').click();await open('同步待上传证据');assert((await text()).includes('没有待同步'),'Sync failed');await page.locator('[data-driver-tab=tasks]').click();assert((await text()).includes('退回处理中'),'Partial delivery failed');await role('dispatch');await action('授权退回仓库',{reason:'回演示仓；人工复核剩余容量与时间窗口'});await role('driver');await action('确认货物已返仓');await role('warehouse');await open('退回点收并结案');await fill({count:1,evidence:'DEMO-RETURN'});await page.locator('#action-form button[type=submit]').click();await page.waitForTimeout(350);assert((await page.locator('#form-error').innerText()).includes('件数'),'Return discrepancy not blocked');await fill({count:2});await submit();assert((await text()).includes('异常已结案'),'Return not closed');results.push('离线排队、同步、部分签收、授权退回、差异阻断 PASS');
  await reset();await select('RF-1024-002');await promise();await offer();await ready();await action('登记收款',{proof:'DEMO-TRANSFER-SCREENSHOT'});await open('记录签收');await fill({receiver:'演示客户',evidence:'DEMO-TRANSFER-POD'});await page.locator('#action-form button[type=submit]').click();await page.waitForTimeout(350);assert((await page.locator('#form-error').innerText()).includes('放货条件'),'Unverified transfer released');await page.getByRole('button',{name:'关闭对话框'}).click();await page.getByRole('button',{name:'关闭对话框'}).click();await role('finance');await action('核验收款',{evidence:'DEMO-BANK-UNIQUE'});await role('driver');await action('记录签收',{receiver:'演示客户',evidence:'DEMO-TRANSFER-POD'});assert((await text()).includes('已送达'),'Verified transfer cannot deliver');results.push('转账未核验阻断、核验后签收 PASS');
  await page.setViewportSize({width:390,height:844});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'Mobile horizontal overflow');await page.screenshot({path:'E:/Dr.RouteFit/prototype/screenshots/driver-mobile.png',fullPage:true});await page.locator('[data-driver-tab=profile]').click();assert((await text()).includes('不能核验收款'),'Driver profile missing');await page.locator('[data-driver-tab=tasks]').click();results.push('390px 司机端、任务/同步/我的 PASS');
  await page.setViewportSize({width:1440,height:1100});await role('dispatch');
  for(const [state,expected] of Object.entries({loading:'正在读取订单',empty:'暂无配送任务',error:'暂时无法读取',unavailable:'数据源尚未接入',stale:'演示数据已过期',degraded:'人工降级演示',forbidden:'无权访问'})){await page.locator('[data-action=qa]').first().click();await page.locator(`[data-mode=${state}]`).click();assert((await text()).includes(expected),'State missing '+state);await page.locator('[data-action=normal]').first().click();}
  results.push('加载、空、错误、不可用、过期、降级、无权限 PASS');
  await open('新建订单');await page.keyboard.press('Escape');assert(!await page.locator('#dialog').isVisible(),'Escape failed');assert(await page.getByRole('button',{name:'新建订单',exact:true}).evaluate(el=>el===document.activeElement),'Focus not restored');results.push('对话框 Escape 与焦点恢复 PASS');
  await reset();await page.screenshot({path:'E:/Dr.RouteFit/prototype/screenshots/dispatch-ready.png',fullPage:true});
  return {browser:'PASS',checks:results};
}
